        case SKX:
        case ICX:
        case SPR:
        case EMR:
        case GNR:
        case GNR_D:
        case GRR:
        case SRF:
            return (serverUncorePMUs.size() && serverUncorePMUs[0].get()) ? (serverUncorePMUs[0]->getNumQPIPorts()) : 0;
