public:
    enum DieTypeBits
    {
        Compute = 1<<23,
        LLC     = 1<<24,
        Memory  = 1<<25,
        IO      = 1<<26
    };
    static std::string getDieTypeStr(const uint64 d)
    {
        std::string type{};
        if (d & UncoreCounterState::Compute)
        {
            type += "COR";
        }
        if (d & UncoreCounterState::IO)
        {
            type += "IO";
        }
        if (d & UncoreCounterState::LLC)
        {
            type += "LLC";
        }
        if (d & UncoreCounterState::Memory)
        {
            type += "M";
        }
        return type;
    }
